import React, { useState, useContext } from "react";
import { useNavigate } from "react-router-dom";
import api from "../api"; // Axios instance
import { AuthContext } from "../contexts/AuthContext";

export default function Login() {
  const [form, setForm] = useState({ email: "", password: "", totp: "" });
  const [error, setError] = useState("");
  const [step, setStep] = useState("credentials"); // "credentials" | "totp"
  const [tempUser, setTempUser] = useState(null);
  const [tempToken, setTempToken] = useState("");
  const { login } = useContext(AuthContext);
  const navigate = useNavigate();

  const handleChange = (e) => setForm({ ...form, [e.target.name]: e.target.value });

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");

    try {
      if (step === "credentials") {
        // Step 1: login with email + password
        const res = await api.post("/auth/login", {
          email: form.email,
          password: form.password,
        });

        const { token, user } = res.data;

        if (!user || !token) {
          setError("Invalid response from server");
          return;
        }

        if (user.role === "student") {
          // Student with TOTP enabled
          if (user.totpSecretEnc) {
            setStep("totp");
            setTempUser(user);
            setTempToken(token);
            return;
          }
        }

        // Admin or Comelec: login immediately
        login({ token, user });
        if (user.role === "admin") navigate("/admin-dashboard");
        else if (user.role === "comelec") navigate("/comelec-dashboard");
      } else if (step === "totp") {
        // Step 2: submit TOTP for student
        const res = await api.post("/auth/login", {
          email: tempUser.email,
          password: form.password,
          totp: form.totp,
        });

        const { token, user } = res.data;
        login({ token, user });
        navigate("/student-dashboard"); // redirect to student dashboard
      }
    } catch (err) {
      console.error(err);
      setError(err.response?.data?.error || "Login failed");
    }
  };

  return (
    <div style={{ display: "flex", justifyContent: "center", padding: "50px", fontFamily: "Arial, sans-serif" }}>
      <div style={{ width: "400px", padding: "30px", border: "1px solid #ddd", borderRadius: "10px", boxShadow: "0 4px 10px rgba(0,0,0,0.1)" }}>
        <h2 style={{ textAlign: "center", marginBottom: "20px", color: "#333" }}>
          {step === "credentials" ? "Login" : "Enter TOTP"}
        </h2>

        <form onSubmit={handleSubmit} style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
          {step === "credentials" && (
            <>
              <input
                type="email"
                name="email"
                placeholder="Email"
                value={form.email}
                onChange={handleChange}
                required
                style={{ padding: "10px", borderRadius: "5px", border: "1px solid #ccc" }}
              />
              <input
                type="password"
                name="password"
                placeholder="Password"
                value={form.password}
                onChange={handleChange}
                required
                style={{ padding: "10px", borderRadius: "5px", border: "1px solid #ccc" }}
              />
            </>
          )}

          {step === "totp" && (
            <>
              <p style={{ textAlign: "center", color: "#555" }}>
                Please enter the 6-digit code from your Authenticator app
              </p>
              <input
                type="text"
                name="totp"
                placeholder="TOTP Code"
                value={form.totp}
                onChange={handleChange}
                required
                style={{ padding: "10px", borderRadius: "5px", border: "1px solid #ccc", textAlign: "center", letterSpacing: "3px" }}
              />
            </>
          )}

          <button
            type="submit"
            style={{
              padding: "12px",
              borderRadius: "5px",
              border: "none",
              backgroundColor: "#007bff",
              color: "#fff",
              fontWeight: "bold",
              cursor: "pointer",
            }}
          >
            {step === "credentials" ? "Login" : "Verify OTP"}
          </button>
        </form>

        {error && <p style={{ marginTop: "20px", textAlign: "center", color: "red" }}>{error}</p>}

        {step === "credentials" && (
          <p style={{ marginTop: "20px", textAlign: "center", color: "#555" }}>
            Don't have an account?{" "}
            <button
              type="button"
              style={{ color: "#007bff", fontWeight: "bold", cursor: "pointer", textDecoration: "underline" }}
              onClick={() => navigate("/register")}
            >
              Register
            </button>
          </p>
        )}
      </div>
    </div>
  );
}
